const wh = $('Cal.com webhook').first().json;
if (wh.body && wh.body.triggerEvent && wh.body.triggerEvent !== 'BOOKING_CREATED') return [];
const payload = (wh.body && wh.body.payload) || {};
const attendee = ((payload.attendees || [])[0]) || {};
const body = $input.first().json;
const opps = (body.data && (body.data.opportunities || Object.values(body.data)[0])) || [];
const active = opps.filter(o => o.stage === 'SEQUENCE_RUNNING' || o.stage === 'REPLIED');
if (!active.length) return [];
const norm = (s) => (typeof s === 'string' ? s : '').toLowerCase().replace(/[^a-z]/g, '');
const aName = norm(attendee.name);
const aEmail = (attendee.email || '').toLowerCase();
const personOf = (o) => o.pointOfContact || null;
let match = null;
let matchedBy = 'recency';
if (aName || aEmail) {
  match = active.find(o => {
    const p = personOf(o);
    if (!p) return false;
    const pn = p.name && typeof p.name === 'object' ? norm((p.name.firstName || '') + (p.name.lastName || '')) : norm(p.name);
    const pe = ((p.emails && p.emails.primaryEmail) || '').toLowerCase();
    return (aEmail && pe && aEmail === pe) || (aName && pn && (pn.includes(aName) || aName.includes(pn)));
  }) || null;
  if (match) matchedBy = 'attendee';
}
if (!match) {
  active.sort((a, b) => new Date(a.updatedAt || 0) - new Date(b.updatedAt || 0));
  match = active[active.length - 1];
}
return [{ json: {
  dealId: match.id,
  dealName: match.name || 'Deal',
  attendeeName: attendee.name || 'The founder',
  when: payload.startTime || '',
  matchedBy,
} }];
